def solve_magic_square():
    n = 5
    magic_sum = 65

    # Clues: index -> value
    clues = {
        6: 5,   # (1,1)
        10: 4,  # (2,0)
        23: 2,  # (4,3)
    }

    # Precompute all 5-element subsets of 1..25 that sum to 65
