    # Find all 5-element subsets of 1..25 summing to 65
    valid_subsets = []
    for combo in combinations(range(1, 26), 5):
        if sum(combo) == 65:
            valid_subsets.append(combo)

    print(f"Found {len(valid_subsets)} valid 5-element subsets summing to 65")

    # Now we need to arrange them in a 5x5 grid such that columns and diagonals also sum to 65
    # This is still complex. Let's try a direct backtracking with the clues.

    # Use a simple backtracking approach
    grid = [0] * 25
    for idx, val in clues.items():
        grid[idx] = val

    used = set(val for val in grid if val != 0)

    def is_valid_partial(grid):
        # Check rows that are complete
        for i in range(5):
            row = grid[i*5:(i+1)*5]
            if 0 not in row:
                if sum(row) != 65:
                    return False
            else:
                # Check if sum can still reach 65
                known_sum = sum(x for x in row if x != 0)
                unknown_count = sum(1 for x in row if x == 0)
                min_needed = sum(range(1, unknown_count + 1))
                max_available = sum(range(26 - unknown_count, 26))
                # More precise: min possible sum for remaining cells
                remaining = [x for x in range(1, 26) if x not in used and x not in row]
                if len(remaining) >= unknown_count:
                    min_add = sum(sorted(remaining)[:unknown_count])
                    max_add = sum(sorted(remaining)[-unknown_count:])
                    if known_sum + min_add > 65 or known_sum + max_add < 65:
                        return False

        # Check columns that are complete
        for j in range(5):
            col = [grid[i*5+j] for i in range(5)]
            if 0 not in col:
                if sum(col) != 65:
                    return False
            else:
                known_sum = sum(x for x in col if x != 0)
                unknown_count = sum(1 for x in col if x == 0)
                remaining = [x for x in range(1, 26) if x not in used and x not in col]
                if len(remaining) >= unknown_count:
                    min_add = sum(sorted(remaining)[:unknown_count])
                    max_add = sum(sorted(remaining)[-unknown_count:])
                    if known_sum + min_add > 65 or known_sum + max_add < 65:
                        return False

        # Check diagonals if complete
        diag1 = [grid[i*5+i] for i in range(5)]
        if 0 not in diag1:
            if sum(diag1) != 65:
                return False

        diag2 = [grid[i*5+(4-i)] for i in range(5)]
        if 0 not in diag2:
            if sum(diag2) != 65:
                return False

        return True

    def solve(pos):
        if pos == 25:
            return is_valid_partial(grid)

        if grid[pos] != 0:
            return solve(pos + 1)

        for val in range(1, 26):
            if val in used:
                continue

            grid[pos] = val
            used.add(val)

            if is_valid_partial(grid):
                if solve(pos + 1):
                    return True

            used.remove(val)
            grid[pos] = 0

        return False

    if solve(0):
